const CitypageBodyContainer = styled.div`
    ${tw`mb-10`};

    min-height: 50vh;
`;

const BlocksDiv = styled.div`
    color: ${theme`colors.primary.dark`};

    display: flex;
    flex-wrap: wrap;
    justify-content: center;
`;

const Block_1 = styled.div`
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-around;
    align-items: center;

    width: 100%;

    margin-bottom: 20px;

    div {
        width: 45%;

        text-align: right;
        position: relative;

        & > svg {
            transform: scale(0.8) translateX(50px);
            transform-origin: center;
        }

        h2,
        h3 {
            font-family: 'Quicksand';
            font-weight: bold;
            text-transform: uppercase;
        }
        h2 {
            font-size: 47px;
            line-height: 59px;
        }
        h3 {
            font-size: 32px;
            line-height: 40px;
        }
        p {
            padding-top: 8px;
            font-weight: normal;
            font-size: 18px;
        }

        @media (max-width: 640px) {
            width: 100%;
            padding-left: 62px;
            padding-right: 62px;
            text-align: center;

            margin-bottom: 64px;
        }
    }
    & > svg {
        width: 40%;

        @media (max-width: 640px) {
            order: -1;
            width: fit-content;
            height: min-content;
            padding-left: 80px;
            padding-right: 80px;
        }
    }

    @media (min-width: 1100px) {
        justify-content: center;
        margin-bottom: 86px;
        div {
            width: 355px;
            margin-right: 64px;

            & > svg {
                transform: scale(1);
            }
            h2 {
                font-size: 48px;
                line-height: 60px;
            }
            h3 {
                font-size: 68px;
                line-height: 85px;
            }
            p {
                white-space: pre-line;
                font-size: 22px;
            }
        }
        svg {
            height: initial;
            width: initial;
        }
    }
`;

